using Ambio.Domain.Common;
using Ambio.Domain.Companies;

namespace Ambio.Domain.Offers;

/// <summary>A job ad, independent of whether it is applied to. It was published, for Ambio, on the day it was
/// recorded: its <see cref="CreatedAt"/>. Its <see cref="ShortId"/> identifies it in its URL (ADR 0025).</summary>
public class JobOffer : ITimeStampable
{
    private readonly List<JobOfferPosting> _postings = [];

    public Guid Id { get; } = Guid.CreateVersion7();

    // Random and unique: generated by Infrastructure, which retries while it is taken.
    public required string ShortId
    {
        get;
        init
        {
            ArgumentException.ThrowIfNullOrWhiteSpace(value);
            field = value;
        }
    }

    // The end client. It becomes optional with the recruiter company (Phase 2b).
    public required Guid CompanyId { get; set; }

    public Company Company { get; private set; } = null!;

    public required string Title
    {
        get;
        set
        {
            ArgumentException.ThrowIfNullOrWhiteSpace(value);
            field = value.Trim();
        }
    }

    // Plain-text copy of the ad, kept when the ad goes offline.
    public string? Description { get; set; }

    public string? Location { get; set; }

    public required ContractType ContractType { get; set; }

    public required RemotePolicy RemotePolicy { get; set; }

    // Free text, as announced: "45–55 k€", "TJM 500".
    public string? Salary { get; set; }

    public DateTime CreatedAt { get; set; }

    public DateTime UpdatedAt { get; set; }

    public DateTime? ArchivedAt { get; set; }

    public IReadOnlyList<JobOfferPosting> Postings => _postings;

    /// <summary>Records a site where the offer was seen. The site and the URL are trimmed; an URL is recorded
    /// only once per offer.</summary>
    /// <exception cref="InvalidOperationException">The offer already has a posting with this URL.</exception>
    public JobOfferPosting AddPosting(string site, string url)
    {
        var posting = new JobOfferPosting { JobOfferId = Id, Site = site, Url = url };

        if (HasPostingWithUrl(posting.Url))
        {
            throw new InvalidOperationException($"The offer already has a posting with the URL {posting.Url}.");
        }

        _postings.Add(posting);
        return posting;
    }

    /// <summary>Whether the offer already has a posting with this URL, compared once trimmed.</summary>
    public bool HasPostingWithUrl(string url) => _postings.Any(p => p.Url == url.Trim());

    /// <summary>An offer keeps at least one posting: only one of several can be removed.</summary>
    public bool CanRemovePosting => _postings.Count > 1;

    /// <summary>Removes a posting of the offer.</summary>
    /// <exception cref="InvalidOperationException">The offer has no posting with this id, or it is its last
    /// one.</exception>
    public void RemovePosting(Guid postingId)
    {
        var posting = _postings.SingleOrDefault(p => p.Id == postingId)
                      ?? throw new InvalidOperationException($"The offer has no posting with the id {postingId}.");

        if (!CanRemovePosting)
        {
            throw new InvalidOperationException("The last posting of an offer can't be removed.");
        }

        _postings.Remove(posting);
    }
}
